window.products.push({"id":1127776,"name":"North Mountain Supply - TNS-BK-12 Twist-N-Seal Closures - Pack of 12 (Black)","category":"homeandappliances","retail price":8.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/8164NhN7nrL._AC_SL1500_.jpg","description":"Our Twist-N-Seal Capsule features an elegant design with the absence of visible threads and creates a tamper evident seal. The capsule is quickly applied by sliding it on the bottle and twisting. Caps remain airtight and can be applied and reapplied repeatedly without loss of effectiveness. The Twist-N-Seal Capsules and bottles are BPA free. We that our products will arrive undamaged and free of defects - Covered under our 30 day hassle free replacement!","images":["https://m.media-amazon.com/images/I/8164NhN7nrL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"North Mountain Supply","source_asin":"B07ZTR73V2","category_path":"Home & Kitchen"},"sku":"BM-1127776","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07ZTR73V2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07ZTR73V2","price_pending":true,"merchant_ready":false});
